 function draftMarkup(){const a=account(),fields=a?.platformId==='zongheng'?[['title','作品名'],['summary','作品简介'],['audience','目标读者（男生／女生）'],['type','一级分类'],['category','二级分类'],['tags','标签（逗号分隔，每类1至3个）'],['protagonist','主角名一'],['secondaryProtagonist','主角名二'],['status','作品状态（连载中）']]:[['title','作品名'],['oneLine','一句话简介'],['summary','作品简介'],['type','作品类型'],['genre','题材'],['category','分类'],['audience','目标读者'],['tags','标签'],['status','创作状态'],['wordCount','预计字数'],['volumeName','待建卷计划']];return `<form class="np-draft"><p>资料先保存在本机。打开当前平台的官网建书页后，可逐项填写并回读核对；不会自动点击创建、保存或发布。</p>${a?.platformId==='fanqie'?`<label>签约模式 <small>必须与官网一致</small><select name="signingMode" aria-label="签约模式"><option value="">请选择模式</option>${['连载模式','完本模式'].map(value=>`<option value="${value}" ${draftFields.signingMode===value?'selected':''}>${value}</option>`).join('')}</select></label>`:''}${fields.map(([key,label])=>`<label>${label} <small>本地资料</small>${key==='summary'?`<textarea rows="4" name="${key}">${h(draftFields[key]||'')}</textarea>`:`<input name="${key}" value="${h(draftFields[key]||'')}" maxlength="20000">`}</label>`).join('')}<div><button type="button" data-np="save-draft">保存本地资料</button></div><output data-draft-state>${draftDirty?'资料待保存':'本地资料已读取'}</output></form>`;}
 function bind(){
  host.onchange=e=>{const t=e.target;void(async()=>{
   if(t.matches('[data-np-account]')){await flushDraft();worksRun++;directoryRun++;selectedAccount=t.value;selectedWork='';selectedVolume='';directory={volumes:[],chapters:[],metadata:{}};publications=[];works={status:'idle',items:[]};newWork=false;message='';await readWorks();paint();}
